BEGIN READ ONLY; SET LOCAL statement_timeout='45s';
SELECT json_build_object('observed_at',statement_timestamp(),
 'inventory',(SELECT json_build_object('posts',count(*),'first_post',min(created_at),'last_post',max(created_at),'entities_present',count(*)FILTER(WHERE entities IS NOT NULL),'raw_handle_bodies',count(*)FILTER(WHERE text LIKE '%@%')) FROM posts),
 'tables',(SELECT json_agg(table_name) FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('posts_brands_mentions','brand_discovery_candidates','brand_discovery_candidate_tokens','untracked_brand_promotion_evidence')),
 'tracked_brands',(SELECT json_agg(nickname ORDER BY nickname) FROM brands WHERE NOT is_sentinel),
 'candidate_names',(SELECT json_agg(x ORDER BY source_posts DESC,id) FROM (SELECT id,observed_name,aliases,candidate_handles,verification_status,jsonb_array_length(source_identities) AS source_posts FROM brand_discovery_candidates ORDER BY source_posts DESC,id LIMIT 100)x),
 'evidence_inventory',(SELECT json_build_object('rows',count(*),'posts',count(DISTINCT source_post_id),'candidates',count(DISTINCT brand_discovery_candidate_id)) FROM untracked_brand_promotion_evidence)
); COMMIT;

BEGIN READ ONLY; SET LOCAL statement_timeout='45s';
WITH source AS MATERIALIZED (
 SELECT tweet_id,author_id,author_handle,is_reply,text
 FROM posts WHERE fetched_at < '2026-09-29T06:19:29.636718+00:00'
), tokens AS (
 SELECT DISTINCT p.tweet_id,p.author_id,p.author_handle,p.is_reply,
 CASE WHEN left(m[1],1)='@' THEN 'handle' ELSE 'domain' END AS kind,
 lower(m[1]) AS token
 FROM source p CROSS JOIN LATERAL regexp_matches(p.text,
 '@[A-Za-z0-9_]+|[A-Za-z0-9][A-Za-z0-9.-]*[.](?:ai|com|io|app|dev|xyz|net|org|co|so)(?![A-Za-z0-9_])','g') m
), counted AS (
 SELECT kind,token,count(*) AS posts,count(DISTINCT author_id) AS authors,
 count(*)FILTER(WHERE NOT coalesce(is_reply,false)) AS nonreply_posts,
 count(*)FILTER(WHERE token='@'||lower(author_handle)) AS self_mentions
 FROM tokens WHERE token NOT IN ('t.co','x.com','twitter.com','www.twitter.com')
 GROUP BY kind,token
), ranked AS (
 SELECT *,row_number()OVER(PARTITION BY kind ORDER BY nonreply_posts DESC,posts DESC,token) AS rank FROM counted
)
SELECT json_build_object('observed_at',statement_timestamp(),'fetched_before','2026-09-29T06:19:29.636718+00:00',
 'rankings',(SELECT json_agg(x ORDER BY kind,rank) FROM ranked x WHERE (kind='handle' AND rank<=160) OR (kind='domain' AND rank<=80)),
 'known_brand_handles',(SELECT json_agg(x) FROM (SELECT lower(a.handle) AS handle,array_agg(DISTINCT ba.brand_id ORDER BY ba.brand_id) AS brands FROM accounts a JOIN brands_accounts ba ON ba.accounts_id=a.author_id JOIN brands b ON b.nickname=ba.brand_id AND NOT b.is_sentinel GROUP BY lower(a.handle))x)
); COMMIT;

BEGIN READ ONLY; SET LOCAL statement_timeout='35s';
SELECT json_build_object('observed_at',statement_timestamp(),'fetched_before','2026-09-29T06:19:29.636718+00:00',
 'identity_audit',(SELECT json_build_object(
 'xpert_email_posts',count(*)FILTER(WHERE text ~* '[a-z0-9._%+-]+@xpertsystems[.]ai\M'),
 'xpert_real_at_mentions',count(*)FILTER(WHERE text ~* '(^|[^a-z0-9._%+-])@xpertsystems\M'),
 'exact_account_sales_footer',count(*)FILTER(WHERE text LIKE '%推特账号 ins账号购买 谷歌账号购买 飞机账号 TG账号%'),
 'exact_footer_authors',count(DISTINCT author_id)FILTER(WHERE text LIKE '%推特账号 ins账号购买 谷歌账号购买 飞机账号 TG账号%'),
 'account_and_posting_terms_overlap',count(*)FILTER(WHERE text ~* '(推特账号|ins账号购买|谷歌账号购买|twitter account purchase|twitter account sales|buy twitter accounts)' AND text ~* '(推特发帖软件|推特营销软件|X账号管理软件|Twitter营销工具|twitter posting software|twitter marketing tool)')
 ) FROM posts WHERE fetched_at<'2026-09-29T06:19:29.636718+00:00' AND text ~* '(xpert|推特账号|ins账号购买|谷歌账号购买|twitter account)'),
 'candidate_inventory',(SELECT json_build_object('total_rows',count(*),'pending',count(*)FILTER(WHERE verification_status='pending')) FROM brand_discovery_candidates),
 'stored_entity_keys',(SELECT json_agg(x ORDER BY posts DESC) FROM (SELECT k.key,count(*) AS posts FROM posts p CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(p.entities)='object' THEN p.entities ELSE '{}'::jsonb END) k(key) WHERE p.fetched_at<'2026-09-29T06:19:29.636718+00:00' AND p.entities IS NOT NULL GROUP BY k.key)x)
); COMMIT;

BEGIN READ ONLY; SET LOCAL statement_timeout='20s';
SELECT json_build_object('observed_at',statement_timestamp(),'fetched_before','2026-09-29T06:19:29.636718+00:00',
 'entity_value_types',(SELECT json_agg(x ORDER BY value_type) FROM (
 SELECT CASE WHEN entities IS NULL THEN 'SQL NULL' ELSE coalesce(jsonb_typeof(entities),'unknown') END AS value_type,count(*) AS posts
 FROM posts WHERE fetched_at<'2026-09-29T06:19:29.636718+00:00'
 GROUP BY 1)x)); COMMIT;
